<?php
namespace App\Http\Controllers\Poultry;
use App\Http\Controllers\Controller;use App\Models\{AnimalGroup,EggCollection,FeedConsumption,HealthEvent,MortalityRecord};use Illuminate\Http\Request;use Illuminate\Support\Carbon;use Illuminate\View\View;use Symfony\Component\HttpFoundation\StreamedResponse;
class PoultryReportController extends Controller{
public function index(Request $r):View{$this->authorizeReport($r);[$from,$to,$batchId]=$this->filters($r);$scope=fn($q,$date)=>$q->whereBetween($date,[$from,$to])->when($batchId,fn($x)=>$x->where('animal_group_id',$batchId));$eggs=$scope(EggCollection::with(['batch','lines.grade','recorder'])->where('status','approved'),'collected_on')->latest('collected_on')->latest('collected_at')->get();$feed=$scope(FeedConsumption::with(['batch','type','recorder'])->where('status','approved'),'used_on')->latest('used_on')->get();$mortality=$scope(MortalityRecord::with(['batch','cause','recorder']),'occurred_on')->latest('occurred_on')->get();$health=$scope(HealthEvent::with(['batch','medication','recorder']),'occurred_on')->latest('occurred_on')->get();$active=AnimalGroup::where('status','active')->when($batchId,fn($q)=>$q->whereKey($batchId))->get();return view('poultry.report.index',['from'=>$from,'to'=>$to,'batchId'=>$batchId,'batches'=>AnimalGroup::orderBy('code')->get(),'active'=>$active,'eggs'=>$eggs,'feed'=>$feed,'mortality'=>$mortality,'health'=>$health,'pendingEggs'=>$scope(EggCollection::where('status','submitted'),'collected_on')->count(),'pendingFeed'=>$scope(FeedConsumption::where('status','submitted'),'used_on')->count()]);}
public function export(Request $r):StreamedResponse{$this->authorizeReport($r);[$from,$to,$batchId]=$this->filters($r);$scope=fn($q,$date)=>$q->whereBetween($date,[$from,$to])->when($batchId,fn($x)=>$x->where('animal_group_id',$batchId));$eggs=$scope(EggCollection::with(['batch','lines.grade'])->where('status','approved'),'collected_on')->get();$feed=$scope(FeedConsumption::with(['batch','type'])->where('status','approved'),'used_on')->get();$mortality=$scope(MortalityRecord::with(['batch','cause']),'occurred_on')->get();$health=$scope(HealthEvent::with(['batch','medication']),'occurred_on')->get();return response()->streamDownload(function()use($eggs,$feed,$mortality,$health,$from,$to){$out=fopen('php://output','w');fwrite($out,"\xEF\xBB\xBF");fputcsv($out,['BROOKS AGRO FARM LTD.']);fputcsv($out,['Poultry Unit Report',$from.' to '.$to]);fputcsv($out,[]);fputcsv($out,['Date','Category','Batch','Description','Quantity','Unit','Status / notes']);foreach($eggs as $x)fputcsv($out,[$x->collected_on->format('Y-m-d'),'Egg collection',$x->batch?->code,ucfirst($x->session).' - '.$x->lines->map(fn($l)=>($l->grade?->name??'Grade').': '.$l->total_eggs)->implode('; '),$x->total_eggs,'eggs','Approved']);foreach($feed as $x)fputcsv($out,[$x->used_on->format('Y-m-d'),'Feed',$x->batch?->code,$x->label(),$x->quantity_kg,'kg','Approved']);foreach($mortality as $x)fputcsv($out,[$x->occurred_on->format('Y-m-d'),'Mortality',$x->batch?->code,$x->cause?->name??$x->worker_note,$x->totalLost(),'birds',ucfirst(str_replace('_',' ',$x->status))]);foreach($health as $x)fputcsv($out,[$x->occurred_on->format('Y-m-d'),'Health',$x->batch?->code,ucfirst($x->event_type).' - '.($x->medication?->name??$x->reason),$x->birds_treated,'birds',$x->findings]);fclose($out);},'poultry-report-'.$from.'-'.$to.'.csv',['Content-Type'=>'text/csv; charset=UTF-8']);}
private function filters(Request $r):array{$from=Carbon::parse($r->query('from',now()->startOfMonth()->toDateString()))->toDateString();$to=Carbon::parse($r->query('to',now()->toDateString()))->toDateString();abort_if($from>$to,422,'The start date must be before the end date.');return [$from,$to,$r->integer('batch')?:null];}private function authorizeReport(Request $r):void{abort_unless($r->user()->canAccess('reports')||$r->user()->canAccess('production')||$r->user()->canAccess('batches')||$r->user()->canAccess('egg-inventory'),403);}}
